const defaultShellRunner: ShellRunner = async (command, root, emit, onCancel) => { return new Promise((resolve) => { const isWin = process.platform === "win32"; const shellCmd = isWin ? "powershell.exe" : (process.env.SHELL || "/bin/sh"); const args = isWin ? ["-NoProfile", "-Command", command] : ["-c", command]; let child: import("node:child_process").ChildProcess; try { child = spawn(shellCmd, args, { cwd: root, env: process.env, shell: false, windowsHide: true, }); } catch (error) { emit(`error: ${error instanceof Error ? error.message : String(error)}`); return resolve(1); } onCancel?.(() => { try { child.kill(); } catch {} }); let stdoutRemainder = ""; child.stdout?.on("data", (chunk: Buffer) => { const text = stdoutRemainder + chunk.toString("utf8"); const lines = text.split(/\r?\n/); stdoutRemainder = lines.pop() ?? ""; for (const line of lines) emit(line); }); let stderrRemainder = ""; child.stderr?.on("data", (chunk: Buffer) => { const text = stderrRemainder + chunk.toString("utf8"); const lines = text.split(/\r?\n/); stderrRemainder = lines.pop() ?? ""; for (const line of lines) emit(line); }); child.on("close", (code) => { if (stdoutRemainder) emit(stdoutRemainder); if (stderrRemainder) emit(stderrRemainder); resolve(code ?? 0); }); child.on("error", (err) => { emit(`error: ${err.message}`); resolve(1); }); }); };
The default shell runner: executes commands in PowerShell on Windows,
or the default user shell ($SHELL or /bin/sh) on POSIX.

const MIN_SUBSTRING_MATCH = 3;
How much the user must type before a mid-name match counts.

Without it a single letter drags in noise — `/w` would offer `new`.

